import unittest
import pytest
from candidate import mean_absolute_deviation


class TestMeanAbsoluteDeviation(unittest.TestCase):

    def test_normal_case_expected_result(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.0, 2.0, 3.0, 4.0]), 1.0)

    def test_three_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([1, 2, 3]), 2 / 3)

    def test_single_element(self):
        self.assertAlmostEqual(mean_absolute_deviation([5]), 0.0)

    def test_all_same_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([3, 3, 3, 3]), 0.0)

    def test_all_zeros(self):
        self.assertAlmostEqual(mean_absolute_deviation([0, 0, 0]), 0.0)

    def test_negative_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([-1, -2, -3]), 2 / 3)

    def test_mixed_positive_and_negative(self):
        self.assertAlmostEqual(mean_absolute_deviation([-1, 0, 1]), 2 / 3)

    def test_mixed_positive_and_negative_two_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([-5, 5]), 5.0)

    def test_float_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([1.5, 2.5, 3.5]), 2 / 3)

    def test_large_numbers(self):
        self.assertAlmostEqual(mean_absolute_deviation([1000, 2000, 3000]), 1000 / 3 * 2)

    def test_two_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([1, 3]), 1.0)

    def test_symmetric_distribution(self):
        self.assertAlmostEqual(mean_absolute_deviation([-2, -1, 0, 1, 2]), 1.2)

    def test_non_uniform_distribution(self):
        self.assertAlmostEqual(mean_absolute_deviation([1, 1, 1, 10]), 3.0)

    def test_integers_return_float(self):
        result = mean_absolute_deviation([1, 2, 3, 4])
        self.assertIsInstance(result, float)

    def test_empty_list_raises_zero_division_error(self):
        with self.assertRaises(ZeroDivisionError):
            mean_absolute_deviation([])

    def test_none_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(None)

    def test_integer_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation(5)

    def test_string_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation("hello")

    def test_list_with_none_elements_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1, None, 3])

    def test_list_with_string_elements_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation([1, "two", 3])

    def test_tuple_input_raises_type_error(self):
        with self.assertRaises(TypeError):
            mean_absolute_deviation((1, 2, 3))

    def test_large_dataset(self):
        data = list(range(1, 101))
        mean = sum(data) / len(data)
        expected = sum(abs(x - mean) for x in data) / len(data)
        self.assertAlmostEqual(mean_absolute_deviation(data), expected)

    def test_very_small_values(self):
        self.assertAlmostEqual(mean_absolute_deviation([0.001, 0.002, 0.003]), 2 / 3 * 0.001)

    def test_result_is_non_negative(self):
        self.assertGreaterEqual(mean_absolute_deviation([-10, 0, 10]), 0)

    def test_two_equal_elements(self):
        self.assertAlmostEqual(mean_absolute_deviation([7, 7]), 0.0)

    def test_large_magnitude_values(self):
        self.assertAlmostEqual(mean_absolute_deviation([1e6, 2e6, 3e6]), 1e6 / 3 * 2)


if __name__ == '__main__':
    unittest.main()
